CREATE SCHEMA IF NOT EXISTS sport_center;
CREATE TABLE sport_center.payment_settlement_batches (
id bigint PRIMARY KEY, company_id integer NOT NULL,status text NOT NULL,
bank_mutation_id bigint, canonical_bank_mutation_id bigint,settlement_journal_id integer,
settlement_date date, provider_code text, bank_account_id text, settlement_rule_version text,
gross_amount numeric,mdr_amount numeric,net_amount numeric,updated_at timestamptz DEFAULT now()
);
CREATE TABLE sport_center.accounting_journals (
id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,journal_type text NOT NULL,
status text NOT NULL,is_reversal boolean NOT NULL DEFAULT false,
reversal_of_id integer,settlement_batch_id bigint,notes text,created_by text,
correlation_id text,posted_at timestamptz,posted_by text,approved_at timestamptz,
approved_by text,source_event_id uuid,settlement_reference text,
gross_amount numeric,dpp_amount numeric,tax_amount numeric,
debit_amount numeric NOT NULL DEFAULT 0,credit_revenue_amount numeric NOT NULL DEFAULT 0,
credit_ppn_amount numeric NOT NULL DEFAULT 0
);
CREATE TABLE sport_center.accounting_journal_lines (
id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
journal_id integer NOT NULL,line_type text,account_code text,account_name text,
amount numeric,description text
);
CREATE TABLE sport_center.payment_settlement_items (
settlement_id bigint,payment_id integer,item_status text,gross_amount numeric
);
CREATE TABLE sport_center.sport_payments (
id integer PRIMARY KEY,company_id integer,amount numeric,status text,
settlement_status text,payment_method text,payment_provider text,bank_account_id text,
paid_at timestamptz,expected_settlement_date text,settlement_rule_version text,
mdr_amount numeric,updated_at timestamptz DEFAULT now()
);
-- Read-only rule-parity gate is exercised against real PostgreSQL, not a mock.
-- Isolated test data only: no shared DEV/PROD configuration mutations.
CREATE TABLE sport_center.payment_settlement_configs (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id integer NOT NULL,
  provider_code text NOT NULL,
  bank_account_id text NOT NULL,
  rule_version text,
  source text NOT NULL,
  is_active boolean NOT NULL,
  mdr_rate numeric,
  calculation_method text,
  fixed_provider_fee numeric,
  fee_tax_rate numeric,
  rounding_scale integer,
  rounding_method text,
  effective_from date,
  effective_until date
);
