CREATE TABLE public.company_bank_accounts (id integer PRIMARY KEY,account_number text,
company_id integer,is_active boolean);
CREATE TABLE public.bank_mutations (
id bigint PRIMARY KEY, status text, journal_entry_id bigint, company_id integer,
amount numeric,transaction_date date,source_classification text,direction text,
approved_at timestamptz,posted_at timestamptz,bank_account_id text,
reconciliation_status text,review_code text,review_reason text,
approved_by text,posted_by text,updated_at timestamptz DEFAULT now()
);
CREATE TABLE public.bank_reconciliation_matches (
id bigint PRIMARY KEY,mutation_id bigint,candidate_type text,candidate_id bigint,
candidate_source text,status text
);
CREATE TABLE public.bank_reconciliation_audit (
id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
mutation_id bigint, action text,actor text,meta jsonb
);
CREATE OR REPLACE FUNCTION sport_center.validate_accounting_journal(p_journal_id integer) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE d numeric; c numeric;
BEGIN
SELECT COALESCE(SUM(amount) FILTER (WHERE line_type='debit'),0),
       COALESCE(SUM(amount) FILTER (WHERE line_type='credit'),0)
INTO d,c FROM sport_center.accounting_journal_lines WHERE journal_id=p_journal_id;
IF d=0 OR d<>c THEN RAISE EXCEPTION 'ACCOUNTING_JOURNAL_UNBALANCED'; END IF;
END $$;
CREATE OR REPLACE FUNCTION sport_center.guard_finalized_settlement_items() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE batch_status text; orig_id integer;
BEGIN
SELECT status, settlement_journal_id INTO batch_status,orig_id
FROM sport_center.payment_settlement_batches WHERE id=NEW.settlement_id;
IF TG_OP='UPDATE' AND current_setting('sport_center.allow_finalized_membership_reversal',true)='owner-audited-compensation-v1'
 AND batch_status='reversed' AND OLD.item_status='active' AND NEW.item_status='reversed'
 AND (to_jsonb(NEW)-'item_status') IS NOT DISTINCT FROM (to_jsonb(OLD)-'item_status')
 AND EXISTS(SELECT 1 FROM sport_center.accounting_journals j JOIN sport_center.accounting_journal_lines l ON l.journal_id=j.id
 WHERE j.reversal_of_id=orig_id AND j.settlement_batch_id=NEW.settlement_id AND j.is_reversal=true
 AND j.status='posted' AND j.journal_type='settlement'
 GROUP BY j.id HAVING SUM(CASE WHEN l.line_type='debit' THEN l.amount ELSE 0 END)=SUM(CASE WHEN l.line_type='credit' THEN l.amount ELSE 0 END))
THEN RETURN NEW; END IF;
IF batch_status IN ('posted','reconciled','reversed') THEN RAISE EXCEPTION 'FINALIZED_SETTLEMENT_ITEMS_ARE_IMMUTABLE'; END IF;
RETURN NEW;
END $$;
CREATE TRIGGER trg_guard_finalized_settlement_items BEFORE UPDATE ON sport_center.payment_settlement_items
FOR EACH ROW EXECUTE FUNCTION sport_center.guard_finalized_settlement_items();
